#include "TextureDocument.hh"
#include <cassert>
#include <cmath>
#include <iostream>
int main(){using namespace bts;const NormalVector flat{0,0,1},a=normalized_normal({.4f,.2f,.89f}),b=normalized_normal({-.25f,.35f,.9f});auto error=[](NormalVector x,NormalVector y){float e=0;for(int c=0;c<3;++c)e=std::max(e,std::abs(x[c]-y[c]));return e;};for(auto mode:{LayerBlend::NormalCombine,LayerBlend::NormalDetail,LayerBlend::NormalInverseDetail}){assert(error(blend_normal(mode,flat,flat),flat)<1e-7);assert(error(blend_normal(mode,a,flat),a)<1e-6);assert(error(blend_normal(mode,flat,a),a)<1e-6);const auto normal=blend_normal(mode,a,b);float length=0;for(float v:normal){assert(std::isfinite(v));length+=v*v;}assert(std::abs(length-1)<1e-6);}
  assert(error(blend_normal(LayerBlend::NormalCombine,a,b),blend_normal(LayerBlend::NormalCombine,b,a))<1e-7);assert(error(blend_normal(LayerBlend::NormalDetail,a,b),blend_normal(LayerBlend::NormalInverseDetail,b,a))<1e-7);assert(error(blend_normal(LayerBlend::NormalCombine,a,b),blend_normal(LayerBlend::NormalDetail,a,b))>.001);assert(error(blend_normal(LayerBlend::NormalDetail,a,b),blend_normal(LayerBlend::NormalInverseDetail,a,b))>.001);
  assert(TextureLayer{}.blending[3]==LayerBlend::NormalDetail);SceneSnapshot scene;MaterialSummary material;material.session_id=1;material.name="Normal";material.uniform_editable=true;scene.materials={material};ImportSummary imported;imported.materials={{1,"Normal"}};TextureDocument doc({},imported,scene);auto &set=doc.set(1);set.channels[3]=true;set.precision[3]=ChannelPrecision::RGB32F;TextureDocument::add_fill(set);const auto lower=set.selected_layer;TextureDocument::layer(set,lower).values.normal=a;TextureDocument::add_fill(set);const auto upper=set.selected_layer;TextureDocument::layer(set,upper).values.normal=b;std::vector<TextureSetBinding> bindings{{set.id,1,set.name}};for(auto mode:{LayerBlend::NormalCombine,LayerBlend::NormalDetail,LayerBlend::NormalInverseDetail}){TextureDocument::layer(set,upper).blending[3]=mode;assert(error(TextureDocument::evaluate(set).material.normal,blend_normal(mode,b,a))<1e-6);const auto data=doc.to_json();assert(TextureDocument::from_json(data,bindings).to_json()==data);}for(int i=0;i<=100;++i){const auto n=normalized_normal({(i-50)/55.f,.2f,.1f});assert(error(reoriented_normal(flat,n),n)<1e-6&&error(reoriented_normal(n,flat),n)<1e-6);}std::cout<<"Distinct whiteout/RNM/inverse RNM, flat identities, swapped order, unit vectors, layer default, evaluated composition and persistence passed\n";}
